import { SpeciesId } from "#enums/species-id";

const CLASSIC_FINAL_BOSS_LOCALE_KEYS: Partial<Record<SpeciesId, string>> = {
  [SpeciesId.ETERNATUS]: "eternatus",
  [SpeciesId.MEWTWO]: "mewtwo",
  [SpeciesId.RAYQUAZA]: "rayquaza",
  [SpeciesId.KYOGRE]: "kyogre",
  [SpeciesId.GROUDON]: "groudon",
  [SpeciesId.NECROZMA]: "necrozma",
  [SpeciesId.DIALGA]: "dialga",
  [SpeciesId.PALKIA]: "palkia",
  [SpeciesId.GIRATINA]: "giratina",
};

export function getClassicFinalBossLocaleKey(speciesId: SpeciesId): string | undefined {
  return CLASSIC_FINAL_BOSS_LOCALE_KEYS[speciesId];
}
