import { globalScene } from "#app/global-scene";
import { UiMode } from "#enums/ui-mode";
import { BattlePhase } from "#phases/battle-phase";
import type { OptionSelectItem } from "#ui/base-option-select-ui-handler";
import i18next from "i18next";

export class SelectFinalPathPhase extends BattlePhase {
  public readonly phaseName = "SelectFinalPathPhase";

  start() {
    super.start();
    this.showIntro();
  }

  private getOptions(includeRecordedMemories = true): OptionSelectItem[] {
    const hasClearParty = !!localStorage.getItem("renew_last_clear_party");
    const options: OptionSelectItem[] = [
      {
        label: i18next.t("battle:finalPath.trialOfLegends.option"),
        handler: () => {
          globalScene.finalPathChoice = 1;
          globalScene.ui.setMode(UiMode.MESSAGE);
          this.endPhase();
          return true;
        },
      },
    ];

    if (includeRecordedMemories) {
      options.push({
        label: i18next.t(
          hasClearParty ? "battle:finalPath.recordedMemories.option" : "battle:finalPath.recordedMemories.lockedOption",
        ),
        handler: () => {
          if (!hasClearParty) {
            globalScene.ui.setMode(UiMode.MESSAGE);
            globalScene.ui.showDialogue(
              i18next.t("battle:finalPath.recordedMemories.lockedDialogue"),
              i18next.t("battle:finalPath.guideName"),
              null,
              () => this.showOptions(false),
            );
            return true;
          }
          globalScene.finalPathChoice = 2;
          globalScene.ui.setMode(UiMode.MESSAGE);
          this.showRouteIntro("battle:finalPath.recordedMemories.selected");
          return true;
        },
      });
    }

    options.push({
      label: i18next.t("battle:finalPath.mtSilver.option"),
      handler: () => {
        globalScene.finalPathChoice = 3;
        globalScene.ui.setMode(UiMode.MESSAGE);
        this.showRouteIntro("battle:finalPath.mtSilver.selected");
        return true;
      },
    });

    return options;
  }

  private showIntro(): void {
    globalScene.ui.showDialogue(
      i18next.t("battle:finalPath.intro"),
      i18next.t("battle:finalPath.guideName"),
      null,
      () => this.showOptions(),
    );
  }

  private showOptions(includeRecordedMemories = true): void {
    globalScene.ui.setMode(UiMode.OPTION_SELECT, {
      options: this.getOptions(includeRecordedMemories),
      delay: 500,
    });
  }

  private endPhase() {
    globalScene.phaseManager.pushNew("NewBattlePhase");
    this.end();
  }

  private showRouteIntro(dialogueKey: string): void {
    globalScene.ui.showDialogue(i18next.t(dialogueKey), i18next.t("battle:finalPath.guideName"), null, () =>
      this.endPhase(),
    );
  }
}
