import { audioManager } from "#app/global-audio-manager";
import { globalScene } from "#app/global-scene";
import { UiMode } from "#enums/ui-mode";
import { BattlePhase } from "#phases/battle-phase";
import i18next from "i18next";

export class GameOverRenewRewardPhase extends BattlePhase {
  public readonly phaseName = "GameOverRenewRewardPhase";

  constructor(private readonly candyCount: number) {
    super();
  }

  start(): void {
    super.start();

    audioManager.playSound("se/level_up_fanfare");
    globalScene.ui.setMode(UiMode.MESSAGE);
    globalScene.ui.fadeIn(250).then(() => {
      globalScene.ui.showText(
        i18next.t("battle:renewClearReward", {
          count: this.candyCount,
          defaultValue: `리뉴 모드 클리어 보상으로\n파티 전원 사탕 ${this.candyCount}개를 받았다!`,
        }),
        null,
        () => {
          globalScene.time.delayedCall(1500, () => globalScene.arenaBg.setVisible(true));
          this.end();
        },
        null,
        true,
        1500,
      );
    });
  }
}
